let state=JSON.parse(localStorage.getItem("nawaf-hq-v3")||"null")||seed;const $=s=>document.querySelector(s),emp=i=>state.employees.find(x=>x.id===i),pr=i=>state.projects.find(x=>x.id===i),save=()=>localStorage.setItem("nawaf-hq-v3",JSON.stringify(state)),add=(text,kind="SIM")=>state.activities.unshift({text,kind}),status=s=>({READY:"جاهز",WORKING:"يعمل",RESEARCHING:"يبحث",COLLABORATING:"يتعاون",REPORTING:"يعد تقريرًا",REVIEWING:"يراجع",WAITING_FOR_NAWAF:"ينتظر نواف",WAITING_APPROVAL:"ينتظر موافقة",COMPLETED:"أكمل العمل",IDLE:"متاح"}[s]||s),avg=()=>Math.round(state.employees.reduce((n,e)=>n+e.productivity,0)/state.employees.length);
function render(){let busy=state.employees.filter(e=>e.status!=="IDLE").length,h='<div class="shell"><aside class="sidebar"><div class="brand">قدّها<small>NAWAF HQ</small></div><div class="brand-copy">شركتك الرقمية الحية</div><nav class="nav"><button class="active">⌂ الرئيسية</button><button id="workforce">♙ موظفو AI</button><button id="projects-nav">▤ المشاريع</button><button id="reports-nav">▧ التقارير</button><button id="add">＋ إضافة موظف</button><button id="rules">⌾ دستور الشركة</button><button id="anal">▥ التحليلات</button></nav><div class="tip">🟢 إجراء متصل<br>🔵 محاكاة داخلية<br>🟠 بانتظار نواف</div></aside><main class="main"><header class="topbar"><div class="ceo"><div class="avatar">N</div><span>نواف<small>الرئيس التنفيذي</small></span></div><input class="search" aria-label="البحث في الشركة" placeholder="ابحث عن موظف أو مشروع أو مهمة..."></header><section class="greeting"><div><h1>👋 صباح الخير يا نواف</h1><p>المدير العام: '+busy+' موظفين نشطين و '+state.decisions.length+' قرار مهم.</p></div><button class="primary" id="advance">تحديث العمل الآن ←</button></section><section class="kpis"><button class="kpi card" data-dashboard="workforce"><b>'+busy+'</b><span>موظفين نشطين</span><em>من الحالة الفعلية</em></button><button class="kpi card" data-dashboard="tasks"><b>'+state.tasks.filter(t=>t.progress===100).length+'</b><span>مهام مكتملة</span><em>من المهام</em></button><button class="kpi card" data-dashboard="reports"><b>'+state.reports.length+'</b><span>تقارير محفوظة</span><em>قابلة للقراءة</em></button><button class="kpi card" data-dashboard="decisions"><b>'+state.decisions.length+'</b><span>موافقات CEO</span><em style="color:#ffbd57">تنتظر نواف</em></button><button class="kpi card" data-dashboard="analytics"><b>'+avg()+'%</b><span>إنتاجية الشركة</span><em>من الموظفين</em></button></section><section class="grid"><div><div class="office card"><div class="section-title"><span>مكتب Nawaf HQ <span class="status"><i class="dot"></i> مباشر الآن</span></span><span class="status">اضغط الموظف أو القسم</span></div><img src="assets/office-small.png" alt="مكتب الشركة الذكي">';
state.employees.forEach((e,i)=>h+='<button class="robot rb'+(i%7)+' state-'+e.status.toLowerCase()+'" data-emp="'+e.id+'" data-status="'+e.status+'"><span class="ai-unit"><i class="antenna"></i><i class="head"><i class="face"><i></i><i></i></i></i><i class="body"></i></span><small>'+e.name+'<em>'+status(e.status)+' · '+e.progress+'%</em></small></button>');h+='<button class="room r1" data-dept="إدارة المشاريع">إدارة المشاريع</button><button class="room r2" data-dept="التصميم">التصميم والإبداع</button><button class="room r3" data-dept="التسويق">التسويق والنمو</button><button class="room r4" data-dept="البحث والابتكار">البحث والابتكار</button><button class="room r5" data-dept="التحليلات">التحليلات والجودة</button><button class="room r6" data-dept="التقنية والتطوير">التقنية والتطوير</button><button class="room r7" data-dept="الأعمال والمالية">الأعمال والمالية</button><button class="command-core" id="manager-core">NAWAF<small>مركز القيادة</small></button></div><section class="lower"><div class="employees card"><h2>القوى العاملة AI <span class="status">سجل موحد</span></h2><div class="employee-row">';
state.employees.forEach(e=>h+='<article class="employee" data-emp="'+e.id+'"><div class="bot state-'+e.status.toLowerCase()+'"><span class="ai-unit"><i class="antenna"></i><i class="head"><i class="face"><i></i><i></i></i></i><i class="body"></i></span></div><b>'+e.name+'</b><small>'+e.role+'</small><small class="live">'+(e.status==="WAITING_APPROVAL"?"🟠":"🟢")+' '+status(e.status)+'</small><div class="bar"><i style="width:'+e.progress+'%"></i></div></article>');h+='</div></div><div class="projects card"><h2>المشاريع النشطة</h2>';state.projects.forEach(p=>h+='<div class="project clickable" data-project="'+p.id+'"><span><b>'+p.name+'</b><small class="status">'+p.phase+'</small></span><span><small>'+p.progress+'%</small><div class="bar"><i style="width:'+p.progress+'%"></i></div></span></div>');h+='</div><button class="metrics card manager-card" id="manager-card"><h2>المدير العام AI</h2><p class="manager">'+(state.decisions.length?"قرار مهم يوقف انتقال العمل للتصميم.":"التدفق مستقر، راقب التقرير القادم.")+'</p><div class="metric-grid"><div class="metric"><b>'+avg()+'%</b><small>إنتاجية</small></div><div class="metric"><b>'+state.employees.filter(e=>e.status==="WAITING_APPROVAL").length+'</b><small>عوائق</small></div></div><small class="open-hint">فتح الملخص التنفيذي ←</small></button></section></div><aside class="side-stack"><section class="side-card card"><h2>مركز موافقات CEO ('+state.decisions.length+')</h2>';
state.decisions.forEach(d=>h+='<div class="approval"><strong>🟠 '+d.title+'</strong><p>'+d.project+' · '+d.requester+' · '+d.cost+'</p><div class="buttons"><button class="ok" data-action="approve" data-id="'+d.id+'">اعتماد وتنفيذ</button><button data-action="changes" data-id="'+d.id+'">تعديلات</button><button data-action="reject" data-id="'+d.id+'">رفض</button></div></div>');h+='</section><section class="side-card card"><h2>بث الشركة المباشر <span class="status">من أحداث النظام</span></h2><div class="feed">';state.activities.slice(0,7).forEach(a=>h+='<div><time>'+(a.kind==="REAL"?"🟢":a.kind==="APPROVAL"?"🟠":"🔵")+'</time><span>'+a.text+'</span></div>');h+='</div></section><section class="side-card card"><h2>التقارير والمخرجات</h2>';state.reports.forEach(r=>h+='<div class="report clickable" data-report="'+r.id+'"><b>'+r.title+'</b><small>'+r.stage+' — '+r.progress+'%</small><div class="bar"><i style="width:'+r.progress+'%"></i></div></div>');h+='</section></aside></section></main></div><div class="modal" id="modal"><div class="dialog" id="dialog"></div></div><div class="toast" id="toast"></div>';$("#app").innerHTML=h;bind()}
function bind(){document.querySelectorAll("[data-emp]").forEach(x=>x.onclick=()=>employee(x.dataset.emp));document.querySelectorAll("[data-project]").forEach(x=>x.onclick=()=>project(x.dataset.project));document.querySelectorAll("[data-dept]").forEach(x=>x.onclick=()=>department(x.dataset.dept));document.querySelectorAll("[data-report]").forEach(x=>x.onclick=()=>report(x.dataset.report));document.querySelectorAll("[data-action]").forEach(x=>x.onclick=()=>approve(x.dataset.action,x.dataset.id));$("#advance").onclick=advance;$("#add").onclick=()=>employee();$("#rules").onclick=rules;$("#anal").onclick=analytics}
function modal(h){$("#dialog").innerHTML=h;$("#modal").classList.add("open");$("#modal").onclick=e=>{if(e.target.id==="modal")$("#modal").classList.remove("open")}}
function employee(i){let e=emp(i)||{name:"",role:"",department:"",project:"قدّها",task:"مهمة جديدة",status:"IDLE",progress:0,productivity:70,instructions:""};modal('<form id="form"><h2>'+(i?"ملف "+e.name:"إضافة موظف AI")+'</h2><p class="muted">🟢 سجل واحد يحدث المكتب والمهام والتحليلات.</p><label>الاسم</label><input name="name" value="'+e.name+'" required><label>الدور</label><input name="role" value="'+e.role+'"><label>القسم</label><input name="department" value="'+e.department+'"><label>المشروع</label><input name="project" value="'+e.project+'"><label>المهمة</label><input name="task" value="'+e.task+'"><label>الحالة</label><select name="status"><option>WORKING</option><option>REPORTING</option><option>WAITING_APPROVAL</option><option>IDLE</option></select><label>التعليمات</label><textarea name="instructions">'+e.instructions+'</textarea><div class="actions"><button type="button" id="close">إغلاق</button><button class="primary">حفظ وتحديث الشركة</button></div></form>');$("#form [name=status]").value=e.status;$("#close").onclick=()=>$("#modal").classList.remove("open");$("#form").onsubmit=x=>{x.preventDefault();let o=Object.fromEntries(new FormData(x.target));if(i)Object.assign(e,o);else state.employees.push(Object.assign({id:"e"+Date.now(),progress:0,productivity:70},o));add("تم تحديث سجل "+o.name,"REAL");save();$("#modal").classList.remove("open");render()}}
function project(i){let p=pr(i),ts=state.tasks.filter(t=>t.project===i);modal("<h2>"+p.name+"</h2><p class=muted>المرحلة: "+p.phase+"</p><h3>المهام</h3>"+ts.map(t=>"<div class=report><b>"+t.title+"</b><small>"+emp(t.employee).name+" · "+t.progress+"%</small><div class=bar><i style='width:"+t.progress+"%'></i></div></div>").join("")+"<h3>العوائق</h3><p>"+p.issues.join("، ")+"</p>")}
function department(n){let es=state.employees.filter(e=>e.department===n);modal("<h2>مساحة "+n+"</h2><p class=muted>طلبات العمل من الأقسام الأخرى تظهر هنا.</p>"+es.map(e=>"<div class=report><b>"+e.name+"</b><small>"+e.task+" · "+status(e.status)+"</small></div>").join(""))}
function report(i){let r=state.reports.find(x=>x.id===i);modal("<h2>"+r.title+"</h2><p class=muted>"+emp(r.author).name+" · "+pr(r.project).name+"</p><h3>"+r.stage+" — "+r.progress+"%</h3><div class=bar><i style='width:"+r.progress+"%'></i></div><p>"+r.content+"</p><p class=muted>🔵 محاكاة داخلية مرتبطة بتقدم المهمة.</p>")}
function approve(a,i){let d=state.decisions.find(x=>x.id===i);if(a==="approve"){state.decisions=[];let t=state.tasks[0];t.progress=55;emp("omar").task="موجز الحملة للتصميم";state.tasks.push({id:"t"+Date.now(),title:"تصاميم حملة قدّها",employee:"lian",project:"q",progress:8});emp("lian").status="WORKING";emp("lian").task="تصاميم حملة قدّها";add("نواف اعتمد: "+d.title,"REAL");add("تم إرسال موجز الحملة إلى قسم التصميم","REAL");toast("تم التنفيذ وانتقل العمل للتصميم")}else if(a==="changes"){add("نواف طلب تعديلات على "+d.title,"APPROVAL");toast("تم إرجاع القرار للتعديلات")}else{state.decisions=[];add("نواف رفض: "+d.title,"APPROVAL");toast("تم إيقاف الطلب")}save();render()}
function advance(){let t=state.tasks.find(t=>t.progress<100&&emp(t.employee).status!=="WAITING_APPROVAL");if(!t)return toast("لا توجد مهمة قابلة للتقدم");t.progress=Math.min(100,t.progress+18);let e=emp(t.employee);e.progress=t.progress;e.status=t.progress===100?"IDLE":"WORKING";add(e.name+" حدّث "+t.title+" إلى "+t.progress+"%","SIM");let r=state.reports.find(r=>r.author===e.id);if(!r&&t.progress>=60){state.reports.push({id:"r"+Date.now(),title:"مخرجات "+t.title,author:e.id,project:t.project,stage:"إعداد التقرير",progress:t.progress,content:"مخرجات محفوظة من سير المهمة."});add(e.name+" بدأ إعداد تقرير قابل للقراءة","SIM")}if(r){r.progress=t.progress;r.stage=t.progress===100?"مكتمل":t.progress>80?"المراجعة":"إعداد التقرير"}if(t.progress===100)add(e.name+" أكمل المهمة وأرسل التقرير للمراجعة","SIM");pr(t.project).progress=Math.min(100,pr(t.project).progress+4);save();toast("تقدم "+t.title+": "+t.progress+"%");render()}
function rules(){modal("<h2>دستور الشركة</h2><div class=report><b>الإنفاق</b><small>$0 spending بدون موافقة نواف الصريحة</small></div><div class=report><b>مُعِين</b><small>أي تغيير للمحتوى الديني يتطلب مراجعة CEO</small></div>")}function analytics(){modal("<h2>تحليلات الشركة</h2><div class=metric-grid><div class=metric><b>"+avg()+"%</b><small>إنتاجية الفريق</small></div><div class=metric><b>"+Math.round(state.tasks.reduce((a,t)=>a+t.progress,0)/state.tasks.length)+"%</b><small>عبء العمل</small></div><div class=metric><b>"+state.tasks.filter(t=>t.progress===100).length+"</b><small>مهام مكتملة</small></div></div><p class=muted>الأرقام مشتقة من حالة الموظفين والمهام.</p>")}function toast(x){let t=$("#toast");t.textContent=x;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2600)}render();
